@@ -0,0 +1,15 @@
+import { AppError } from "../errors.js";
+
+/** A request-local store sharing data, ids and persistence with the original. */
+export function forSite(store, site = "main") {
+  if (!store.data.sites.some((s) => s.id === site))
+    throw new AppError("unknown_site", { id: site });
+  const scoped = Object.create(store);
+  scoped.site = site;
+  return scoped;
+}
+
+/** Whether a location belongs to the store's selected site (main by default). */
+export function inSite(store, location) {
+  return store.data.locations.some((l) => l.id === location && l.site === (store.site ?? "main"));
+}
