+++ b/tests/sites.test.js
@@ -0,0 +1,63 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+test("site headers isolate stock, batches, alerts and value while sharing items", async () => {
+  const { store, handle } = app();
+  store.data.batches.push({ ...store.data.batches[3], id: store.nextId("batch"), location: "annex-fridge", qty: 3 });
+  const annex = { "X-Larder-Site": "annex" };
+  const get = async (path, headers = {}) => (await handle({ path, headers })).body;
+  assert.equal((await get("/items/2")).onHand, 10);
+  assert.equal((await get("/items/2", annex)).onHand, 3);
+  assert.equal((await get("/items", annex)).length, store.data.items.length);
+  assert.equal((await get("/batches", annex)).length, 1);
+  assert.equal((await handle({ path: "/batches/4", headers: annex })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/4/waste", headers: annex, body: { qty: 1 } })).status, 404);
+  assert.deepEqual((await get("/alerts", annex)).expiring.map((b) => b.location), ["annex-fridge"]);
+  assert.equal((await get("/reports/stock-value", annex)).totalCents, 387);
+  const bad = await handle({ path: "/items", headers: { "x-larder-site": "missing" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+});
+
+test("cooking cannot use another site's ingredients and leaves stock intact", async () => {
+  const { store, handle } = app();
+  const before = structuredClone(store.data);
+  const result = await handle({ method: "POST", path: "/recipes/2/cook", headers: { "x-larder-site": "annex" }, body: { portions: 1 } });
+  assert.equal(result.status, 409);
+  assert.deepEqual(store.data, before);
+});
+
+test("stock-takes reject locations and ids in another site", async () => {
+  const { handle } = app();
+  const headers = { "x-larder-site": "annex" };
+  const post = (path, body, h = headers) => handle({ method: "POST", path, body, headers: h });
+  assert.equal((await post("/stocktakes", { location: "fridge" })).status, 400);
+  const take = (await post("/stocktakes", { location: "annex-fridge" })).body;
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 4, counted: 1 })).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {}, {})).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {})).status, 200);
+});
+
+test("annex cooking consumes only annex batches and receipts stay in site", async () => {
+  const { store, handle } = app();
+  const headers = { "x-larder-site": "annex" };
+  const original = structuredClone(store.data.batches);
+  for (const itemId of [2, 3, 4]) {
+    store.data.batches.push({
+      ...original.find((b) => b.itemId === itemId),
+      id: store.nextId("batch"), location: "annex-fridge", qty: 10,
+    });
+  }
+  const cooked = await handle({ method: "POST", path: "/recipes/2/cook", headers, body: { portions: 10 } });
+  assert.equal(cooked.status, 200);
+  assert.deepEqual(store.data.batches.slice(0, original.length), original);
+  assert.deepEqual(store.data.batches.slice(original.length).map((b) => b.qty), [8, 9.8, 9.8]);
+  const before = structuredClone(store.data);
+  const received = await handle({
+    method: "POST", path: "/orders/2/receive", headers,
+    body: { lots: [{ lot: "a", location: "annex-fridge" }, { lot: "b", location: "fridge" }] },
+  });
+  assert.equal(received.status, 400);
+  assert.deepEqual(store.data, before);
+});
